'2|110008|55.00|40.00|34.90|41.00|42.50||40.00',
'2|110009|55.00|40.00|34.90|41.00|42.50||40.00',
'2|110010|55.00|40.00|34.90|41.00|42.50||40.00',
'2|110019|55.00|40.00|34.90|41.00|42.50||40.00',
'2|110026|55.00|40.00|34.90|41.00|42.50||40.00',
