'6032|670705|42.00|||41.00|||',
'6032|670706|42.00|||41.00|||',
'6032|670721|42.00|||41.00|||',
'6032|671221|42.00|||41.00|||',
'6032|671329|42.00|||41.00|||',
'6032|673308|42.00|||41.00|||',
'6032|673311|42.00|||41.00|||',
'6032|673312|42.00|||41.00|||',
'6032|673313|42.00|||41.00|||',
'6032|673316|42.00|||41.00|||',
'6032|673501|42.00|||41.00|||',
'6032|673517|42.00|||41.00|||',
'6032|673579|42.00|||41.00|||',
'6032|673589|42.00|||41.00|||',
'6032|673596|42.00|||41.00|||',
'6032|673615|42.00|||41.00|||'
  ]) v
),
priced AS (
  SELECT cm.*, CASE LOWER(COALESCE(carrier_name, ''))
    WHEN 'delhivery' THEN pl.delhivery_charge
    WHEN 'bluedart' THEN pl.bluedart_charge
    WHEN 'dtdc' THEN pl.dtdc_charge
    WHEN 'ekart' THEN pl.ekart_charge
    WHEN 'shadowfax' THEN pl.shadowfax_charge
    WHEN 'amazon' THEN pl.amazon_charge
    WHEN 'elastic' THEN pl.elastic_charge
    ELSE NULL
  END AS carrier_charge,
         NULL AS carrier_zone
  FROM calculated_metrics cm
  LEFT JOIN price_lookup pl
    ON pl.warehouse_id = cm.warehouse_id AND pl.pincode = cm.pincode
)
-- 10. Final Projection
SELECT
  master_shipment_id,
  child_shipment_id,
  effective_shipment_id,
  order_id,
  awb,
  shipment_status,
  invoice_value,
  weight,
  vol_weight,
  cpt_date,
  cpt_handover_date,
  latest_log_status,
  latest_primary_status,
  latest_secondary_status,
  fulfillment_type,
  warehouse_id,
  warehouse_name,
  postal_code,
  hub_id,
  ship_city,
  pincode,
  state,
  carrier_id,
  carrier_name,
  picklist_carrier_id,
  FT_RB_FLAG,
  carrier_switch,
  order_type,
  is_retailer,
  payment_method,
  order_time,
  lsc_handover_time,
  pickup_time,
  dispatch_time,
  lsc_dispatched_time,
  intransit_time,
  ofd1_time,
  ofd2_time,
  ofd3_time,
  delivery_time,
  lsc_delivered_time,
  edd_max_time,
  edd_date,
  updated_edd_max,
  rto_marked_date,
  rto_received_date,
  rto_received_time,
  rto_inward_date,
  rto_inward_time,
  total_attempts,
  tenant,
  sub_tenant,
  shipment_quantity,
  cpt_breach,
  edd_breach,
  otif_breach,
  
  CASE 
    WHEN cpt_breach = 1 AND edd_breach = 0 THEN 'cpt_breach'
    WHEN cpt_breach = 0 AND edd_breach = 1 THEN 'ops_breach'
    WHEN cpt_breach = 1 AND edd_breach = 1 THEN 'cpt_breach'
    ELSE 'no_breach'
  END AS breach_type,
  carrier_charge,
  carrier_zone
FROM priced
ORDER BY edd_date DESC, effective_shipment_id;
